from pathlib import Path
import re,json,hashlib
raw=Path('hoyle.txt').read_text()
source='hoyle-1909'
expected='5d505fa9f6202340eb55313b8ef607b816087a860d3d51b1bf92b5f65240645e'
assert hashlib.sha256(Path('hoyle.txt').read_bytes()).hexdigest()==expected
norm=lambda x:re.sub(r'\s+',' ',x).strip()
text=norm(raw)
start=text.index('{427}'); end=text.index('{447}',start)
slice_text=text[start:end]
entries=[]
def passage(q, page=None, external=False):
    q=norm(q)
    hay=text if external else slice_text
    matches=[m.start() for m in re.finditer(re.escape(q),hay)]
    if not matches: raise ValueError('QUOTE NOT FOUND: '+q)
    offsets=[i+(0 if external else start) for i in matches]
    if page is not None:
        offsets=[i for i in offsets if int(re.findall(r'\{(\d+)\}',text[:i])[-1])==page]
    if len(offsets)!=1: raise ValueError(('NONUNIQUE QUOTE',q[:90],page,offsets))
    i=offsets[0]
    actual=int(re.findall(r'\{(\d+)\}',text[:i])[-1])
    return q,actual

def add(id,name,kind,q,note,*,section=None,scope='in',question=None,deps=(),enabled=(),suspended=(),refs=(),defines=(),page=None,external=False,**extra):
    evidence,p=passage(q,page,external)
    citation='DRAUGHTS / '+(section+' / ' if section else '')+'p. '+str(p)
    e=dict(id=id,name=name,locator=dict(sourceId=source,citation=citation),kind=kind,scope=scope,clarity='ambiguous' if question else 'clear',dependsOn=list(deps),evidence=evidence,status='mapped' if scope=='in' else 'declined',note=note)
    if question:e['ambiguity']=dict(question=question,fate='unresolved',unresolvedReason='RequiresInterpretation' if scope=='in' else 'OutsideCurrentScope')
    if enabled:e['enabledBy']=list(enabled)
    if suspended:e['suspendedBy']=list(suspended)
    if refs:e['crossReferences']=[dict(cites=c,**({'resolvedBy':r} if r else {'unmapped':u})) for c,r,u in refs]
    if defines:e['defines']=[dict(vocabulary='draughts-terms',term=t) for t in defines]
    e.update(extra)
    entries.append(e)
    return e

