raw_advice=raw[raw.index('It is generally better to keep your men'):raw.index('THE NAMES OF THE VARIOUS OPENINGS AND HOW FORMED.')]
advice_paras=[norm(x) for x in re.split(r'\n\s*\n',raw_advice) if x.strip()]
for n,p in enumerate(advice_paras,1):
    refs=[]
    if '(see _post_)' in p:
        refs=[('(see _post_)','elementary-position-names','')]
        for name,target in [('First','first-position-data'),('Second','second-position-data'),('Third','third-position-data'),('Fourth','fourth-position-data')]:
            refs.append((name,target,''))
    add('advice-'+str(n),'General advice paragraph '+str(n),'operation',p,'Read and declined as coaching: '+[
        'centralisation and comparative power do not prescribe move legality.',
        'exchanges, opening plans, pace of learning and choice of opponents are recommendations.',
        'complexity and concentration are strategic recommendations.',
        'the prohibition on touching board squares is presented as playing manners alongside a habit of moving off-hand; it supplies no touch-piece or move-legality rule.',
        'taking quickly reinforces good pace but supplies no replacement for the separately mapped Time law.',
        'attention to an opponent\'s plans is advice.',
        'the one-man-ahead claim is a strategic assessment, not an automatic win condition overriding no-play loss.',
        'study of named endings is recommended; the pointers resolve to their definition entries.'
    ][n-1],scope='out',section=advice_section,refs=refs)

